sys_script_include.script:
function IsValidAppName(strName)
{
	strName = (strName == null) ? '' : String(strName);
	if (strName == '')
	{
		return false;
	}
	if (strName.trim() != strName)
	{
		return false;
	}
	// Disallow caret ^ anywhere
	if (strName.indexOf('^') !== -1)
		return false;

	// The regex allows letters, digits, spaces, and these special chars: @ _ - / ( ) . : ' ’ , ? and hyphen
	// Colon is allowed anywhere except at start or end
	// Also allow digits anywhere, and allow the first character to be @ or letter or digit
	// Added apostrophe ' and right single quotation mark ’ to allowed characters to fix failed cases like "ITSM Roles - Request Management (do not activate, see plugin description)"
	// Added comma ',' and question mark '?' to allowed characters to fix failed cases like "Social Q&A" and similar
	if (!/^[@A-Za-z0-9]([_\&\-\/A-Za-z0-9\s\(\)\.:'’\,\?\-]*)$/.test(strName))
		return false;

	// Colon cannot be first or last character
	if (strName.charAt(0) === ':' || strName.charAt(strName.length - 1) === ':')
		return false;

	// Additional check: string must contain at least one letter or digit (to reject strings with only spaces or punctuation)
	if (!/[A-Za-z0-9]/.test(strName))
		return false;

	// Additional check: string must contain at least one letter (to reject strings with only digits and punctuation)
	if (!/[A-Za-z]/.test(strName))
		return false;

	return true;
}
